  1→import {
  2→  useCallback,
  3→  useRef,
  4→  useState,
  5→  type ReactNode,
  6→} from 'react';
  7→import { AgentContext } from '../hooks/useAgent';
  8→import { runAgentLoop, runAgentEditLoop } from '../agent/agentService';
  9→import type { ChatMessage, ContentSegment, ToolCallResult } from '../types';
 10→
 11→function generateId() {
 12→  return Math.random().toString(36).slice(2, 10);
 13→}
 14→
 15→export function AgentProvider({
 16→  children,
 17→  refreshTables,
 18→}: {
 19→  children: ReactNode;
 20→  refreshTables: () => Promise<void>;
 21→}) {
 22→  const [messages, setMessages] = useState<ChatMessage[]>([]);
 23→  const [isStreaming, setIsStreaming] = useState(false);
 24→  const abortRef = useRef<AbortController | null>(null);
 25→  const textBufferRef = useRef('');
 26→  const flushTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
 27→  const assistantIdRef = useRef('');
 28→  const segmentsRef = useRef<ContentSegment[]>([]);
 29→  const currentTextRef = useRef('');
 30→  const sessionIdRef = useRef<string | null>(null);
 31→
 32→  const flushText = useCallback(() => {
 33→    const text = textBufferRef.current;
 34→    if (!text) return;
 35→    const id = assistantIdRef.current;
 36→    currentTextRef.current += text;
 37→    setMessages((prev) =>
 38→      prev.map((m) =>
 39→        m.id === id ? { ...m, content: m.content + text } : m
 40→      )
 41→    );
 42→    textBufferRef.current = '';
 43→  }, []);
 44→
 45→  const sendMessage = useCallback(
 46→    async (text: string) => {
 47→      if (isStreaming) return;
 48→
 49→      const userMsg: ChatMessage = {
 50→        id: generateId(),
 51→        role: 'user',
 52→        content: text,
 53→      };
 54→
 55→      const assistantId = generateId();
 56→      assistantIdRef.current = assistantId;
 57→      const assistantMsg: ChatMessage = {
 58→        id: assistantId,
 59→        role: 'assistant',
 60→        content: '',
 61→        toolCalls: [],
 62→        isStreaming: true,
 63→      };
 64→
 65→      setMessages((prev) => [...prev, userMsg, assistantMsg]);
 66→      setIsStreaming(true);
 67→      textBufferRef.current = '';
 68→      segmentsRef.current = [];
 69→      currentTextRef.current = '';
 70→
 71→      const controller = new AbortController();
 72→      abortRef.current = controller;
 73→
 74→      await runAgentLoop(
 75→        text,
 76→        sessionIdRef.current,
 77→        {
 78→          onTextChunk: (chunk) => {
 79→            textBufferRef.current += chunk;
 80→            if (!flushTimerRef.current) {
 81→              flushTimerRef.current = setTimeout(() => {
 82→                flushText();
 83→                flushTimerRef.current = null;
 84→              }, 50);
 85→            }
 86→          },
 87→          onThinkingDone: () => {
 88→            // Extended thinking just ended and a text block is starting.
 89→            // Create a thinking segment from accumulated thinking text.
 90→            if (flushTimerRef.current) {
 91→              clearTimeout(flushTimerRef.current);
 92→              flushTimerRef.current = null;
 93→            }
 94→            flushText();
 95→            if (currentTextRef.current.trim()) {
 96→              segmentsRef.current.push({ type: 'thinking', text: currentTextRef.current });
 97→              currentTextRef.current = '';
 98→            }
 99→            setMessages((prev) =>
100→              prev.map((m) =>
101→                m.id === assistantId
102→                  ? { ...m, currentPhase: 'answer', segments: [...segmentsRef.current] }
103→                  : m
104→              )
105→            );
106→          },
107→          onToolCall: (pending: ToolCallResult) => {
108→            if (flushTimerRef.current) {
109→              clearTimeout(flushTimerRef.current);
110→              flushTimerRef.current = null;
111→            }
112→            flushText();
113→            if (currentTextRef.current.trim()) {
114→              segmentsRef.current.push({ type: 'thinking', text: currentTextRef.current });
115→              currentTextRef.current = '';
116→            }
117→            // Add a pending tool segment so the input is shown immediately
118→            segmentsRef.current.push({
119→              type: 'tool',
120→              toolResult: pending,
121→            });
122→            setMessages((prev) =>
123→              prev.map((m) =>
124→                m.id === assistantId
125→                  ? { ...m, segments: [...segmentsRef.current] }
126→                  : m
127→              )
128→            );
129→          },
130→          onToolResult: (result: ToolCallResult) => {
131→            // Merge result into pending tool segment (keep input info, add output)
132→            const pendingIdx = segmentsRef.current.findIndex(
133→              (s) => s.type === 'tool' && s.toolResult?.toolCallId === result.toolCallId
134→            );
135→            if (pendingIdx !== -1) {
136→              const pending = segmentsRef.current[pendingIdx].toolResult!;
137→              segmentsRef.current[pendingIdx] = {
138→                type: 'tool',
139→                toolResult: {
140→                  ...pending,
141→                  ...result,
142→                  toolName: result.toolName || pending.toolName,
143→                  command: result.command || pending.command,
144→                  toolInput: result.toolInput || pending.toolInput,
145→                },
146→              };
147→            } else {
148→              segmentsRef.current.push({ type: 'tool', toolResult: result });
149→            }
150→            setMessages((prev) =>
151→              prev.map((m) =>
152→                m.id === assistantId
153→                  ? { ...m, toolCalls: [...(m.toolCalls || []), result], segments: [...segmentsRef.current] }
154→                  : m
155→              )
156→            );
157→            refreshTables();
158→          },
159→          onDone: (newSessionId) => {
160→            if (newSessionId) sessionIdRef.current = newSessionId;
161→            if (flushTimerRef.current) {
162→              clearTimeout(flushTimerRef.current);
163→              flushTimerRef.current = null;
164→            }
165→            flushText();
166→            if (currentTextRef.current.trim()) {
167→              segmentsRef.current.push({
168→                type: 'answer',
169→                text: currentTextRef.current,
170→              });
171→              currentTextRef.current = '';
172→            }
173→            setMessages((prev) =>
174→              prev.map((m) =>
175→                m.id === assistantId
176→                  ? { ...m, isStreaming: false, currentPhase: undefined, segments: [...segmentsRef.current] }
177→                  : m
178→              )
179→            );
180→            setIsStreaming(false);
181→            abortRef.current = null;
182→          },
183→          onError: (error) => {
184→            if (flushTimerRef.current) {
185→              clearTimeout(flushTimerRef.current);
186→              flushTimerRef.current = null;
187→            }
188→            flushText();
189→            setMessages((prev) =>
190→              prev.map((m) =>
191→                m.id === assistantId
192→                  ? { ...m, content: m.content + `\n\n**Error:** ${error}`, isStreaming: false }
193→                  : m
194→              )
195→            );
196→            setIsStreaming(false);
197→            abortRef.current = null;
198→          },
199→        },
200→        controller.signal
201→      );
202→    },
203→    [isStreaming, flushText, refreshTables]
204→  );
205→
206→  const editMessage = useCallback(
207→    async (messageIndex: number, newContent: string) => {
208→      if (isStreaming) return;
209→
210→      // Build conversation history from messages before the edit point
211→      const conversationHistory: { role: string; content: string }[] = [];
212→      for (let i = 0; i < messageIndex; i++) {
213→        const msg = messages[i];
214→        if (msg.role === 'user' || msg.role === 'assistant') {
215→          conversationHistory.push({ role: msg.role, content: msg.content });
216→        }
217→      }
218→
219→      const assistantId = generateId();
220→      assistantIdRef.current = assistantId;
221→
222→      const userMsg: ChatMessage = {
223→        id: generateId(),
224→        role: 'user',
225→        content: newContent,
226→      };
227→      const assistantMsg: ChatMessage = {
228→        id: assistantId,
229→        role: 'assistant',
230→        content: '',
231→        toolCalls: [],
232→        isStreaming: true,
233→      };
234→
235→      setMessages((prev) => [...prev.slice(0, messageIndex), userMsg, assistantMsg]);
236→      setIsStreaming(true);
237→      textBufferRef.current = '';
238→      segmentsRef.current = [];
239→      currentTextRef.current = '';
240→
241→      const controller = new AbortController();
242→      abortRef.current = controller;
243→
244→      await runAgentEditLoop(
245→        newContent,
246→        conversationHistory,
247→        {
248→          onTextChunk: (chunk) => {
249→            textBufferRef.current += chunk;
250→            if (!flushTimerRef.current) {
251→              flushTimerRef.current = setTimeout(() => {
252→                flushText();
253→                flushTimerRef.current = null;
254→              }, 50);
255→            }
256→          },
257→          onThinkingDone: () => {
258→            if (flushTimerRef.current) {
259→              clearTimeout(flushTimerRef.current);
260→              flushTimerRef.current = null;
261→            }
262→            flushText();
263→            if (currentTextRef.current.trim()) {
264→              segmentsRef.current.push({ type: 'thinking', text: currentTextRef.current });
265→              currentTextRef.current = '';
266→            }
267→            setMessages((prev) =>
268→              prev.map((m) =>
269→                m.id === assistantId
270→                  ? { ...m, currentPhase: 'answer', segments: [...segmentsRef.current] }
271→                  : m
272→              )
273→            );
274→          },
275→          onToolCall: (pending: ToolCallResult) => {
276→            if (flushTimerRef.current) {
277→              clearTimeout(flushTimerRef.current);
278→              flushTimerRef.current = null;
279→            }
280→            flushText();
281→            if (currentTextRef.current.trim()) {
282→              segmentsRef.current.push({ type: 'thinking', text: currentTextRef.current });
283→              currentTextRef.current = '';
284→            }
285→            segmentsRef.current.push({ type: 'tool', toolResult: pending });
286→            setMessages((prev) =>
287→              prev.map((m) =>
288→                m.id === assistantId
289→                  ? { ...m, segments: [...segmentsRef.current] }
290→                  : m
291→              )
292→            );
293→          },
294→          onToolResult: (result: ToolCallResult) => {
295→            const pendingIdx = segmentsRef.current.findIndex(
296→              (s) => s.type === 'tool' && s.toolResult?.toolCallId === result.toolCallId
297→            );
298→            if (pendingIdx !== -1) {
299→              const pending = segmentsRef.current[pendingIdx].toolResult!;
300→              segmentsRef.current[pendingIdx] = {
301→                type: 'tool',
302→                toolResult: {
303→                  ...pending,
304→                  ...result,
305→                  toolName: result.toolName || pending.toolName,
306→                  command: result.command || pending.command,
307→                  toolInput: result.toolInput || pending.toolInput,
308→                },
309→              };
310→            } else {
311→              segmentsRef.current.push({ type: 'tool', toolResult: result });
312→            }
313→            setMessages((prev) =>
314→              prev.map((m) =>
315→                m.id === assistantId
316→                  ? { ...m, toolCalls: [...(m.toolCalls || []), result], segments: [...segmentsRef.current] }
317→                  : m
318→              )
319→            );
320→            refreshTables();
321→          },
322→          onDone: (newSessionId) => {
323→            if (newSessionId) sessionIdRef.current = newSessionId;
324→            if (flushTimerRef.current) {
325→              clearTimeout(flushTimerRef.current);
326→              flushTimerRef.current = null;
327→            }
328→            flushText();
329→            if (currentTextRef.current.trim()) {
330→              segmentsRef.current.push({ type: 'answer', text: currentTextRef.current });
331→              currentTextRef.current = '';
332→            }
333→            setMessages((prev) =>
334→              prev.map((m) =>
335→                m.id === assistantId
336→                  ? { ...m, isStreaming: false, currentPhase: undefined, segments: [...segmentsRef.current] }
337→                  : m
338→              )
339→            );
340→            setIsStreaming(false);
341→            abortRef.current = null;
342→          },
343→          onError: (error) => {
344→            if (flushTimerRef.current) {
345→              clearTimeout(flushTimerRef.current);
346→              flushTimerRef.current = null;
347→            }
348→            flushText();
349→            setMessages((prev) =>
350→              prev.map((m) =>
351→                m.id === assistantId
352→                  ? { ...m, content: m.content + `\n\n**Error:** ${error}`, isStreaming: false }
353→                  : m
354→              )
355→            );
356→            setIsStreaming(false);
357→            abortRef.current = null;
358→          },
359→        },
360→        controller.signal
361→      );
362→    },
363→    [isStreaming, messages, flushText, refreshTables]
364→  );
365→
366→  const deleteMessage = useCallback(
367→    (messageIndex: number) => {
368→      if (isStreaming) return;
369→
370→      setMessages((prev) => prev.slice(0, messageIndex));
371→
372→      // Clear session so next message starts fresh
373→      sessionIdRef.current = null;
374→    },
375→    [isStreaming]
376→  );
377→
378→  const clearMessages = useCallback(() => {
379→    if (abortRef.current) {
380→      abortRef.current.abort();
381→    }
382→    setMessages([]);
383→    setIsStreaming(false);
384→    sessionIdRef.current = null;
385→  }, []);
386→
387→  return (
388→    <AgentContext.Provider
389→      value={{ messages, isStreaming, sendMessage, editMessage, deleteMessage, clearMessages }}
390→    >
391→      {children}
392→    </AgentContext.Provider>
393→  );
394→}
