file.content:
/* ===== Theme Tokens ===== */
:root {
  /* Backgrounds */
  --color-bg-primary: #fff;
  --color-bg-secondary: #f9fafb;
  --color-bg-tertiary: #f5f5f5;
  --color-bg-code: #f3f4f6;
  --color-bg-hover: #f0f7ff;
  --color-bg-hover-strong: #e8e8e8;
  --color-bg-user-msg: #eef2ff;

  /* Text */
  --color-text-primary: #333;
  --color-text-secondary: #1f2937;
  --color-text-tertiary: #374151;
  --color-text-code: #4b5563;
  --color-text-muted: #666;
  --color-text-subtle: #6b7280;
  --color-text-disabled: #9ca3af;
  --color-text-faint: #999;

  /* Borders */
  --color-border-faint: #eee;
  --color-border-light: #e5e7eb;
  --color-border-medium: #ddd;
  --color-border-dark: #d1d5db;
  --color-border-dashed: #ccc;

  /* Accent - Primary (indigo) */
  --color-accent-primary: #6366f1;
  --color-accent-primary-hover: #4f46e5;
  --color-accent-primary-active: #4338ca;
  --color-accent-primary-light: #818cf8;
  --color-accent-primary-border: #c7d2fe;
  --color-accent-primary-shadow: rgba(99, 102, 241, 0.15);
  --color-accent-primary-shadow-strong: rgba(129, 140, 248, 0.2);

  /* Accent - Secondary (blue) */
  --color-accent-secondary: #4a90d9;
  --color-accent-secondary-hover: #357abd;
  --color-accent-secondary-shadow: rgba(74, 144, 217, 0.2);

  /* Error (red) */
  --color-error: #dc2626;
  --color-error-hover: #b91c1c;
  --color-error-text: #b91c1c;
  --color-error-text-dark: #991b1b;
  --color-error-bg: #fef2f2;
  --color-error-bg-hover: #fee2e2;
  --color-error-bg-subtle: #fee;

toolUseResult.originalFile:
.message-bubble {
  padding: 10px 14px;
  border-radius: 10px;
  margin-bottom: 10px;
}

.message-bubble--user {
  background: var(--color-bg-user-msg);
  margin-left: 32px;
}

.message-bubble--assistant {
  background: var(--color-bg-primary);
  border: 1px solid var(--color-border-light);
  margin-right: 32px;
}

.message-bubble__header {
  display: flex;
  align-items: center;
  gap: 4px;
  font-size: 11px;
  font-weight: 600;
  color: var(--color-text-subtle);
  margin-bottom: 4px;
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.message-bubble__content {
  font-size: 14px;
  line-height: 1.5;
  color: var(--color-text-secondary);
}

.message-bubble__content p {
  margin: 0 0 8px;
}

.message-bubble__content p:last-child {
  margin-bottom: 0;
}

.message-bubble__content pre {
  background: var(--color-bg-code);
  padding: 8px 12px;
  border-radius: 6px;
  overflow-x: auto;
  font-size: 12px;
}

.message-bubble__content code {
  background: var(--color-bg-code);
  padding: 1px 4px;
  border-radius: 3px;
  font-size: 13px;
}

.message-bubble__content pre code {
  background: none;
  padding: 0;
}

.message-bubble__content table {
  border-collapse: collapse;
  width: 100%;
  margin: 8px 0;
  font-size: 13px;
  overflow-x: auto;
  display: block;
}

.message-bubble__content th,
.message-bubble__content td {
  border: 1px solid var(--color-border-dark);
  padding: 6px 10px;
  text-align: left;
  white-space: nowrap;
}

.message-bubble__content th {
  background: var(--color-bg-code);
  font-weight: 600;
}

.message-bubble__content tr:nth-child(even) {
  background: var(--color-bg-secondary);
}

.message-bubble__typing {
  font-style: italic;
  background: linear-gradient(
    90deg,
    var(--color-text-disabled) 0%,
    var(--color-text-disabled) 40%,
    var(--color-primary) 50%,
    var(--color-text-disabled) 60%,
    var(--color-text-disabled) 100%
  );
  background-size: 200% 100%;
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
  animation: shimmer 2s ease-in-out infinite;
}

@keyframes shimmer {
  0% {
    background-position: 100% 0;
  }
  100% {
    background-position: -100% 0;
  }
}

.message-bubble__tools {
  margin-top: 8px;
}

/* Segments layout */
.message-bubble__segments {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.message-bubble__segment {
  border-radius: 6px;
  padding: 8px 12px;
}

.message-bubble__segment--thinking {
  background: var(--color-bg-secondary);
  border-left: 3px solid var(--color-border-dark);
}

.message-bubble__segment--answer {
  background: var(--color-success-bg);
  border-left: 3px solid var(--color-success-border);
}

.message-bubble__segment-label {
  font-size: 10px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  color: var(--color-text-disabled);
  margin-bottom: 4px;
}

.message-bubble__segment-label--answer {
  color: var(--color-success-text);
}

.message-bubble__segment-content {
  font-size: 14px;
  line-height: 1.5;
  color: var(--color-text-secondary);
}

.message-bubble__segment-content p {
  margin: 0 0 8px;
}

.message-bubble__segment-content p:last-child {
  margin-bottom: 0;
}

.message-bubble__segment-content pre {
  background: var(--color-bg-code);
  padding: 8px 12px;
  border-radius: 6px;
  overflow-x: auto;
  font-size: 12px;
}

.message-bubble__segment-content code {
  background: var(--color-bg-code);
  padding: 1px 4px;
  border-radius: 3px;
  font-size: 13px;
}

.message-bubble__segment-content pre code {
  background: none;
  padding: 0;
}

.message-bubble__segment-content table {
  border-collapse: collapse;
  width: 100%;
  margin: 8px 0;
  font-size: 13px;
  overflow-x: auto;
  display: block;
}

.message-bubble__segment-content th,
.message-bubble__segment-content td {
  border: 1px solid var(--color-border-dark);
  padding: 6px 10px;
  text-align: left;
  white-space: nowrap;
}

.message-bubble__segment-content th {
  background: var(--color-bg-code);
  font-weight: 600;
}

.message-bubble__segment-content tr:nth-child(even) {
  background: var(--color-bg-secondary);
}

/* Collapsible thinking segments */
.message-bubble__collapsible {
  cursor: default;
}

.message-bubble__collapsible-summary {
  display: flex;
  align-items: center;
  gap: 8px;
  cursor: pointer;
  list-style: none;
  user-select: none;
}

.message-bubble__collapsible-summary::-webkit-details-marker {
  display: none;
}

.message-bubble__collapsible-summary::before {
  content: '▶';
  font-size: 9px;
  color: var(--color-text-disabled);
  transition: transform 0.15s ease;
  flex-shrink: 0;
}

.message-bubble__collapsible[open] > .message-bubble__collapsible-summary::before {
  transform: rotate(90deg);
}

.message-bubble__collapsible-summary .message-bubble__segment-label {
  margin-bottom: 0;
  flex-shrink: 0;
}

.message-bubble__collapsible-preview {
  font-size: 12px;
  color: var(--color-text-disabled);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  min-width: 0;
}

.message-bubble__collapsible[open] > .message-bubble__collapsible-summary .message-bubble__collapsible-preview {
  display: none;
}

.message-bubble__thinking-body {
  display: flex;
  flex-direction: column;
  gap: 8px;
  margin-top: 8px;
}

.message-bubble__tool-segment {
  margin: 2px 0;
}

/* Hover actions for user messages */
.message-bubble__actions {
  display: none;
  margin-left: auto;
  gap: 4px;
}

.message-bubble--user:hover .message-bubble__actions {
  display: inline-flex;
}

.message-bubble__action-btn {
  background: none;
  border: none;
  cursor: pointer;
  padding: 2px 4px;
  font-size: 14px;
  color: var(--color-text-disabled);
  border-radius: 4px;
  line-height: 1;
}

.message-bubble__action-btn:hover {
  background: var(--color-border-light);
  color: var(--color-text-tertiary);
}

.message-bubble__action-btn--delete:hover {
  background: var(--color-error-bg-hover);
  color: var(--color-error);
}

/* Edit mode */
.message-bubble__edit-mode {
  margin-top: 4px;
}

.message-bubble__edit-textarea {
  width: 100%;
  padding: 8px 10px;
  border: 1px solid var(--color-accent-primary-border);
